import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong();
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            long coins = nextLong();
            // Largest k with k(k+1)/2 <= coins: double an upper bound, then binary search.
            long lo = 0, hi = 1;
            while (hi * (hi + 1) / 2 <= coins) hi *= 2;
            while (lo + 1 < hi) {
                long mid = (lo + hi) / 2;
                if (mid * (mid + 1) / 2 <= coins) lo = mid;
                else hi = mid;
            }
            if (i > 0) sb.append(' ');
            sb.append(lo);
        }
        System.out.println(sb);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n := int(nextInt())
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for i := 0; i < n; i++ {
		coins := nextInt()
		// Largest k with k(k+1)/2 <= coins: double an upper bound, then binary search.
		lo, hi := int64(0), int64(1)
		for hi*(hi+1)/2 <= coins {
			hi *= 2
		}
		for lo+1 < hi {
			mid := (lo + hi) / 2
			if mid*(mid+1)/2 <= coins {
				lo = mid
			} else {
				hi = mid
			}
		}
		if i > 0 {
			w.WriteByte(' ')
		}
		w.WriteString(strconv.FormatInt(lo, 10))
	}
	w.WriteByte('\n')
}
